# -*- coding: utf-8 -*-
from abc import ABC, abstractmethod
import datetime
from typing import Union

from httpdbg.utils import get_new_uuid
from httpdbg.utils import HTTPDBGCookie
from httpdbg.utils import HTTPDBGHeader


class HTTPRecordReqResp(ABC):

    @abstractmethod
    def get_header(self, name: str, default: str = "") -> str:
        pass

    @property
    @abstractmethod
    def rawheaders(self) -> bytes:
        pass

    @property
    @abstractmethod
    def headers(self) -> list[HTTPDBGHeader]:
        pass

    @property
    @abstractmethod
    def content(self) -> bytes:
        pass

    @property
    @abstractmethod
    def preview(self):
        pass

    @property
    @abstractmethod
    def rawdata(self) -> bytes:
        pass

    @rawdata.setter
    @abstractmethod
    def rawdata(self, value: bytes):
        pass


class HTTPRecordRequest(HTTPRecordReqResp, ABC):

    @property
    @abstractmethod
    def cookies(self) -> list[HTTPDBGCookie]:
        pass

    @property
    @abstractmethod
    def method(self) -> str:
        pass

    @property
    @abstractmethod
    def uri(self) -> str:
        pass

    @property
    @abstractmethod
    def protocol(self) -> str:
        pass


class HTTPRecordResponse(HTTPRecordReqResp, ABC):

    @property
    @abstractmethod
    def cookies(self) -> list[HTTPDBGCookie]:
        pass

    @property
    @abstractmethod
    def protocol(self) -> str:
        pass

    @property
    @abstractmethod
    def status_code(self) -> int:
        pass

    @property
    @abstractmethod
    def message(self) -> str:
        pass


class HTTPRecord(ABC):
    request: HTTPRecordRequest
    response: HTTPRecordResponse

    @abstractmethod
    def __init__(
        self,
        initiator_id: str,
        group_id: str,
        tag: str = None,
        tbegin: datetime.datetime = None,
        is_client: bool = True,
    ) -> None:
        self.id = get_new_uuid()
        self.address: tuple[str, int] = ("", 0)
        self._url: Union[str, None] = None
        self.initiator_id: str = initiator_id
        self.exception: Union[Exception, None] = None
        self.ssl: Union[bool, None] = None
        self.tbegin: datetime.datetime = datetime.datetime.now(datetime.timezone.utc)
        self.tag: Union[str, None] = tag
        self.group_id: str = group_id
        self.is_client: bool = is_client
        if tbegin:
            self.tbegin = tbegin
        self.http100: bool = False

    @property
    @abstractmethod
    def url(self) -> str:
        pass

    @url.setter
    @abstractmethod
    def url(self, value: str) -> None:
        pass

    @property
    @abstractmethod
    def method(self) -> str:
        pass

    @property
    @abstractmethod
    def status_code(self) -> int:
        pass

    @property
    @abstractmethod
    def reason(self) -> str:
        pass

    @property
    @abstractmethod
    def netloc(self) -> str:
        pass

    @property
    @abstractmethod
    def urlext(self) -> str:
        return self.url[len(self.netloc) :]

    @property
    @abstractmethod
    def in_progress(self) -> bool:
        pass

    @property
    @abstractmethod
    def last_update(self) -> datetime.datetime:
        pass

    @abstractmethod
    def receive_data(self, data: bytes):
        pass

    @abstractmethod
    def send_data(self, data: bytes):
        pass

    @property
    @abstractmethod
    def protocol(self) -> str:
        pass

import datetime
import sys
from typing import Union

from httpdbg.hooks.record import HTTPRecord
from httpdbg.initiator import Group
from httpdbg.initiator import Initiator
from httpdbg.log import logger
from httpdbg.utils import get_new_uuid


class HTTPRecordsSessionInfo:

    def __init__(self):
        self.id: str = get_new_uuid()
        self.command_line: str = " ".join(sys.argv[1:]) if sys.argv[1:] else "console"
        self.tbegin: datetime.datetime = datetime.datetime.now(datetime.timezone.utc)


class HTTPRecords:
    def __init__(
        self,
        client: bool = True,
        server: bool = False,
        ignore: tuple[tuple[str, int], ...] = (),
    ) -> None:
        self.client: bool = client
        self.server: bool = server
        self._ignore: tuple[tuple[str, int], ...] = ignore
        self.reset()

    def reset(self) -> None:
        from httpdbg.hooks.socket import TracerHTTP1

        logger().info("HTTPRecords.reset")
        self.session: HTTPRecordsSessionInfo = HTTPRecordsSessionInfo()
        self.requests: dict[str, HTTPRecord] = {}
        self.requests_already_loaded = 0
        self.initiators: dict[str, Initiator] = {}
        self.current_initiator: Union[str, None] = None
        self.groups: dict[str, Group] = {}
        self.current_group: Union[str, None] = None
        self.current_tag: Union[str, None] = None
        self._tracerhttp1: TracerHTTP1 = TracerHTTP1(ignore=self.ignore)

    @property
    def unread(self) -> int:
        return self.requests_already_loaded < len(self.requests)

    def __getitem__(self, item: int) -> HTTPRecord:
        return list(self.requests.values())[item]

    def __len__(self) -> int:
        return len(self.requests)

    def add_new_record_exception(
        self, initiator: Initiator, group: Group, url: str, exception: Exception
    ) -> HTTPRecord:
        from httpdbg.hooks.recordhttp1 import HTTP1Record, HTTP2Record

        if initiator.id not in self.initiators:
            self.initiators[initiator.id] = initiator
        # Default to HTTP1Record for exceptions, but could potentially be extended to support HTTP2
        # For now, we'll still default to HTTP1Record as we don't have context about protocol
        new_record = HTTP1Record(initiator.id, group.id)
        new_record.url = url
        new_record.exception = exception
        self.requests[new_record.id] = new_record
        return new_record

    def add_initiator(self, initiator: Initiator):
        self.initiators[initiator.id] = initiator
        self.current_initiator = initiator.id

    def add_group(self, group: Group):
        self.groups[group.id] = group
        self.current_group = group.id

    @property
    def ignore(self) -> tuple[tuple[str, int], ...]:
        return self._ignore

    @ignore.setter
    def ignore(self, value) -> None:
        self._ignore = value
        self._tracerhttp1.ignore = value

    def _print_for_debug(self):
        for request in self.requests.values():
            print(f"+ {request.url}")
            print(f"  - initiator: {self.initiators[request.initiator_id].label}")
            print(f"  - group: {self.groups[request.group_id].label}")

